select es.*,bs.first_start_time,bs.first_end_time,bs.second_start_time,bs.second_end_time,bs.name as scheduleName from employee_schedule es left join base_schedule bs on es.schedule_id = bs.id where es.work_date >= #{startDate} and es.work_date <= #{endDate} and es.employee_id in
#{item}
order by es.work_date

