mapper.select:
select * from employee_schedule where DATE_FORMAT(work_date,'%Y-%m-%d') =
DATE_FORMAT(#{workDate},'%Y-%m-%d')
and employee_id = #{employeeId}

select es.employee_id,es.clinic_id,es.work_date,es.schedule_id,bs.type from employee_schedule es
left join base_schedule bs on es.schedule_id = bs.id
where
es.work_date >= #{startDate} and es.work_date <= #{endDate} and es.employee_id = #{employeeId}

  and es.clinic_id = #{clinicId}

order by es.work_date

select es.employee_id,es.clinic_id,es.work_date ,es.schedule_id  ,bs.type,bs.first_start_time startTime,IFNULL(bs.second_end_time,bs.first_end_time) endTime from employee_schedule es
left join base_schedule bs on es.schedule_id = bs.id
where
es.work_date = #{workDate} and es.employee_id = #{employeeId}

  and es.clinic_id = #{clinicId}

order by es.work_date

select es.id, es.employee_id as employeeId, es.clinic_id as clinicId, es.work_date as workDate, es.schedule_id as scheduleId from employee_schedule es where es.inservice = 1
and es.id in
#{item}

select es.id, es.employee_id as employeeId, es.clinic_id as clinicId, es.work_date as workDate, es.schedule_id as scheduleId, bs.type, bs.name, bs.first_start_time as firstStartTime, bs.first_end_time as firstEndTime, bs.second_start_time as secondStartTime, bs.second_end_time as secondEndTime, bs.inservice from employee_schedule es left join base_schedule bs on es.schedule_id = bs.id
es.inservice = 1 and bs.inservice = 1
and bs.type = #{queryForm.type}
and es.employee_id = #{queryForm.userId}
and es.employee_id in
#{item}
and DATE_FORMAT(es.work_date,'%Y-%m-%d') = DATE_FORMAT(#{queryForm.workDate},'%Y-%m-%d')
and DATE_FORMAT(es.work_date,'%Y-%m-%d') in
DATE_FORMAT(#{item},'%Y-%m-%d')
and DATE_FORMAT(es.work_date,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenWorkDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andWorkDate},'%Y-%m-%d')
order by bs.first_start_time asc;

select es.id, es.employee_id as employeeId, es.clinic_id as clinicId, es.work_date as workDate, es.schedule_id as scheduleId, bs.type, bs.name, bs.first_start_time as firstStartTime, bs.first_end_time as firstEndTime, bs.second_start_time as secondStartTime, bs.second_end_time as secondEndTime, bs.inservice from employee_schedule es left join base_schedule bs on es.schedule_id = bs.id
es.inservice = 1 and bs.inservice = 1
and es.employee_id = #{employeeId}
and es.schedule_id = #{scheduleId}
and DATE_FORMAT(es.work_date,'%Y-%m-%d') = DATE_FORMAT(#{workDateString},'%Y-%m-%d')
and es.clinic_id = #{clinicId}
